//! navidrome tool surface.
//!
//! Endpoint registry: `navidrome.{list, detail, create, update, delete}` —
//! generated by `#[endpoint_resource]`.
//!
//! Domain tools, all over Navidrome's Subsonic API:
//!   - `navidrome.server_info`         identity + protocol version
//!   - `navidrome.libraries`           configured music folders
//!   - `navidrome.library.scan`        trigger a rescan (incremental/full)
//!   - `navidrome.library.scan_status` poll an in-progress scan
//!   - `navidrome.now_playing`         who/what is currently streaming

use plugin_toolkit::prelude::*;

use crate::api::{MusicFolder, Navidrome, NowPlayingEntry, ScanStatus, ServerInfo};

#[endpoint_resource(plugin = "navidrome")]
pub struct NavidromeEndpoint {
    pub name: String,
    pub username: String,
    /// Sent as the Subsonic `p` query param (plaintext, over the connection
    /// the endpoint's route resolves to).
    #[secret]
    pub password: String,
    /// Skip TLS verification (self-signed certs).
    pub insecure: bool,
    pub enabled: bool,
}

pub async fn connect(name: &str) -> Result<Navidrome> {
    let password = plugin_toolkit::secrets::resolve_scoped("navidrome", name, "password")?;
    let row = endpoint_db::require(name)?;
    if !row.enabled {
        bail!("navidrome endpoint '{name}' is disabled");
    }
    let base_url = route::resolve_reachable(name, &row.routes, row.insecure).await?;
    Navidrome::new(
        &base_url,
        &row.username,
        password.expose_secret(),
        row.insecure,
    )
}

#[orca_struct(args)]
pub struct EndpointArgs {
    /// Registered navidrome endpoint name.
    #[arg(long)]
    pub name: String,
}

/// Server identity and Subsonic protocol version (`ping.view`).
#[orca_tool(domain = "navidrome", verb = "server_info", role = "read")]
async fn navidrome_server_info(args: EndpointArgs, _ctx: &ToolCtx) -> Result<ServerInfo> {
    connect(&args.name).await?.server_info().await
}

/// Configured music folders (`getMusicFolders.view`).
#[orca_tool(domain = "navidrome", verb = "libraries", role = "read")]
async fn navidrome_libraries(args: EndpointArgs, _ctx: &ToolCtx) -> Result<Vec<MusicFolder>> {
    connect(&args.name).await?.music_folders().await
}

#[orca_struct(args)]
pub struct ScanArgs {
    /// Registered navidrome endpoint name.
    #[arg(long)]
    pub name: String,
    /// Reprocess every file instead of only changed ones.
    #[arg(long)]
    #[serde(default)]
    pub full: bool,
}

/// Trigger a library rescan (`startScan.view`). Navidrome queues the scan and
/// returns at once; poll `navidrome.library.scan_status` for progress.
#[orca_tool(
    domain = "navidrome",
    verb = "library.scan",
    role = "admin",
    execute_gated = true
)]
async fn navidrome_library_scan(args: ScanArgs, _ctx: &ToolCtx) -> Result<ScanStatus> {
    connect(&args.name).await?.start_scan(args.full).await
}

/// Progress of an in-progress (or most recent) scan (`getScanStatus.view`).
#[orca_tool(domain = "navidrome", verb = "library.scan_status", role = "read")]
async fn navidrome_library_scan_status(args: EndpointArgs, _ctx: &ToolCtx) -> Result<ScanStatus> {
    connect(&args.name).await?.scan_status().await
}

/// Who/what is currently streaming (`getNowPlaying.view`).
#[orca_tool(domain = "navidrome", verb = "now_playing", role = "read")]
async fn navidrome_now_playing(args: EndpointArgs, _ctx: &ToolCtx) -> Result<Vec<NowPlayingEntry>> {
    connect(&args.name).await?.now_playing().await
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn tools_declare_roles_and_gating() {
        let role = |n| plugin_toolkit::dispatch::required_role(n);
        for n in [
            "navidrome.server_info",
            "navidrome.libraries",
            "navidrome.library.scan_status",
            "navidrome.now_playing",
        ] {
            assert_eq!(role(n), Some("read"), "{n}");
        }
        assert_eq!(role("navidrome.library.scan"), Some("admin"));
        assert!(plugin_toolkit::dispatch::execute_gated_names().contains(&"navidrome.library.scan"));
    }

    #[test]
    fn connect_fails_when_the_password_secret_is_missing() {
        use std::sync::{Arc, Mutex};
        let caps = Arc::new(Mutex::new(Vec::new()));
        let log = caps.clone();
        let e = plugin_toolkit::capsink::with_cap_sink(
            Box::new(move |cap: &str, _: &str| {
                log.lock().unwrap().push(cap.to_string());
                match cap {
                    "secret.op" => Ok(json!({"value": null}).to_string()),
                    _ => Err(format!("unexpected {cap}")),
                }
            }),
            || {
                tokio::runtime::Builder::new_current_thread()
                    .build()
                    .unwrap()
                    .block_on(connect("nav"))
                    .err()
                    .unwrap()
            },
        );
        assert!(format!("{e:#}").contains("navidrome"), "{e:#}");
    }
}
